<script>
import AsideVue from "@/components/AsideVue.vue";
import Introduction from "@/assets/video/instruction.mp4";
import github from "@/assets/image/follow/github.png";
import email from "@/assets/image/follow/email.png";
import logo from "@/assets/image/logo.jpg";
import {ArrowLeft, ArrowRight, Search, Warning} from "@element-plus/icons-vue";
import axios from "axios";

export default {
  name: "Index",
  computed: {
    ArrowRight() {
      return ArrowRight
    },
    ArrowLeft() {
      return ArrowLeft
    },
    Search() {
      return Search
    }
  },
  components: {
    AsideVue,
  },
  data() {
    return {
      activeName: '1',
      selectedCategory: '',
      selectedItem: '',
      categories: [
        {value: '1', label: '第一章  数据结构概述'},
        {value: '2', label: '第二章  顺序表'},
        {value: '3', label: '第三章  栈和队列'},
        {value: '4', label: '第四章  串'},
        {value: '5', label: '第五章  树'},
        {value: '6', label: '第六章  图'},
        {value: '7', label: '第七章  查找'},
        {value: '8', label: '第八章  排序'},
      ],
      items: [],
      showVideo: true,
      playid: "",
      cameraEnabled: false,
      cameraRequesting: false,
      cameraPermissionDenied: false,
      cameraStatus: 'idle',
      cameraPreviewVisible: false,
      mediaStream: null,
      mediaRecorder: null,
      recordedChunks: [],
      captureTimer: null,
      initialCaptureTimer: null,
      countdownTimer: null,
      nextCaptureSeconds: 600,
      latestAttention: null,
      learningStartTime: 0,
      learningDuration: 0,
      isVideoPlaying: false,
      pageVisible: true,
    }
  },
  computed: {
    nextCaptureTime() {
      const mins = Math.floor(this.nextCaptureSeconds / 60);
      const secs = this.nextCaptureSeconds % 60;
      return `${mins}:${secs.toString().padStart(2, '0')}`;
    },
    username() {
      return localStorage.getItem('username') || '';
    },
    role() {
      return localStorage.getItem('role') || 'student';
    }
  },
  mounted() {
    document.addEventListener('visibilitychange', this.handleVisibilityChange);
    window.addEventListener('mouseleave', this.handleMouseLeave);
    window.addEventListener('mouseenter', this.handleMouseEnter);
  },
  beforeUnmount() {
    this.stopAllCapture();
    document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    window.removeEventListener('mouseleave', this.handleMouseLeave);
    window.removeEventListener('mouseenter', this.handleMouseEnter);
  },
  methods: {
    async initCamera() {
      if (this.role !== 'student') return true;
      if (this.mediaStream && this.mediaStream.getVideoTracks().some(track => track.readyState === 'live')) {
        this.cameraEnabled = true;
        return true;
      }
      if (this.cameraRequesting) return false;
      this.cameraRequesting = true;
      try {
        if (!navigator.mediaDevices?.getUserMedia) throw new Error('当前浏览器不支持摄像头访问');
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { width: 640, height: 480 },
          audio: false
        });
        this.mediaStream = stream;
        this.cameraEnabled = true;
        this.cameraPermissionDenied = false;
        stream.getVideoTracks().forEach(track => {
          track.onended = () => {
            this.cameraEnabled = false;
            this.mediaStream = null;
            if (this.$refs.videoPlayer) this.$refs.videoPlayer.pause();
            this.$message.error('摄像头访问已关闭，慕课视频已暂停。重新授权后才能继续播放。');
          };
        });
        console.log('摄像头已启用');
        return true;
      } catch (err) {
        console.error('摄像头权限获取失败:', err);
        this.cameraEnabled = false;
        this.cameraPermissionDenied = true;
        if (this.$refs.videoPlayer) this.$refs.videoPlayer.pause();
        this.$message.error('必须允许摄像头访问才能播放学习视频。请在浏览器地址栏中重新开启摄像头权限。');
        return false;
      } finally {
        this.cameraRequesting = false;
      }
    },
    openCameraPreview() {
      if (this.mediaStream && this.$refs.previewVideo) {
        this.$refs.previewVideo.srcObject = this.mediaStream;
        this.cameraPreviewVisible = true;
      }
    },
    startCaptureSchedule() {
      if (this.captureTimer) return;
      this.nextCaptureSeconds = 600;
      this.startCountdown();
      this.captureTimer = setInterval(() => {
        this.startRecording();
      }, 10 * 60 * 1000);
      console.log('已启动定时采集：每10分钟采集一次');
    },
    stopCaptureSchedule() {
      if (this.captureTimer) {
        clearInterval(this.captureTimer);
        this.captureTimer = null;
      }
      if (this.countdownTimer) {
        clearInterval(this.countdownTimer);
        this.countdownTimer = null;
      }
      console.log('已停止定时采集');
    },
    startCountdown() {
      if (this.countdownTimer) clearInterval(this.countdownTimer);
      this.nextCaptureSeconds = 600;
      this.countdownTimer = setInterval(() => {
        if (this.nextCaptureSeconds > 0) {
          this.nextCaptureSeconds--;
        }
      }, 1000);
    },
    startRecording() {
      if (!this.mediaStream || !this.isVideoPlaying || !this.pageVisible) {
        console.log('跳过采集：视频未播放或页面不可见');
        this.nextCaptureSeconds = 600;
        return;
      }
      this.cameraStatus = 'recording';
      this.recordedChunks = [];
      try {
        this.mediaRecorder = new MediaRecorder(this.mediaStream, {
          mimeType: 'video/webm;codecs=vp8'
        });
        this.mediaRecorder.ondataavailable = (event) => {
          if (event.data.size > 0) {
            this.recordedChunks.push(event.data);
          }
        };
        this.mediaRecorder.onstop = () => {
          this.cameraStatus = 'monitoring';
          this.uploadAndAnalyze();
          this.nextCaptureSeconds = 600;
        };
        this.mediaRecorder.start();
        setTimeout(() => {
          if (this.mediaRecorder && this.mediaRecorder.state === 'recording') {
            this.mediaRecorder.stop();
          }
        }, 10 * 1000);
        console.log('开始录制10秒视频片段');
      } catch (err) {
        console.error('录制失败:', err);
        this.cameraStatus = 'monitoring';
        this.nextCaptureSeconds = 600;
      }
    },
    async uploadAndAnalyze() {
      if (this.recordedChunks.length === 0) return;
      const blob = new Blob(this.recordedChunks, { type: 'video/webm' });
      const formData = new FormData();
      formData.append('video', blob, 'clip.webm');
      formData.append('username', this.username);
      formData.append('chapter', this.selectedCategory);
      formData.append('subchapter', this.selectedItem);
      formData.append('learning_duration', Math.floor(this.learningDuration));
      try {
        const response = await axios.post('/api/analyzeStudentLearning', formData, {
          headers: { 'Content-Type': 'multipart/form-data' }
        });
        if (response.data && response.data.status === 'success') {
          this.latestAttention = response.data.attention_score;
          console.log('分析完成，专注度:', response.data.attention_score);
          if (response.data.attention_score < 40) {
            this.$message.warning('检测到专注度较低，请集中注意力学习！');
          }
        }
      } catch (err) {
        console.error('上传分析失败:', err);
      }
    },
    async onVideoPlay() {
      if (this.role === 'student' && !this.cameraEnabled) {
        this.$refs.videoPlayer?.pause();
        const allowed = await this.initCamera();
        if (!allowed) return;
        try { await this.$refs.videoPlayer?.play(); } catch (error) { console.error('恢复播放失败:', error); }
        return;
      }
      this.isVideoPlaying = true;
      if (!this.learningStartTime) {
        this.learningStartTime = Date.now();
      }
      if (this.cameraEnabled) {
        this.startCaptureSchedule();
        if (!this.initialCaptureTimer) {
          this.initialCaptureTimer = setTimeout(() => {
            this.initialCaptureTimer = null;
            if (this.isVideoPlaying) this.startRecording();
          }, 1500);
        }
      }
    },
    onVideoPause() {
      this.isVideoPlaying = false;
      if (this.learningStartTime) {
        this.learningDuration += (Date.now() - this.learningStartTime) / 1000;
        this.learningStartTime = 0;
      }
      if (this.initialCaptureTimer) {
        clearTimeout(this.initialCaptureTimer);
        this.initialCaptureTimer = null;
      }
      this.reportLearningProgress();
    },
    handleVisibilityChange() {
      this.pageVisible = !document.hidden;
      if (document.hidden && this.isVideoPlaying && this.$refs.videoPlayer) {
        this.$refs.videoPlayer.pause();
        this.$message.info('检测到离开页面，视频已暂停');
      }
    },
    handleMouseLeave(e) {
      if (e.clientY <= 0 || e.clientX <= 0 || e.clientX >= window.innerWidth || e.clientY >= window.innerHeight) {
        this.pageVisible = false;
        if (this.isVideoPlaying && this.$refs.videoPlayer) {
          this.$refs.videoPlayer.pause();
          this.$message.info('检测到鼠标离开页面，视频已暂停');
        }
      }
    },
    handleMouseEnter() {
      this.pageVisible = true;
    },
    stopAllCapture() {
      this.stopCaptureSchedule();
      if (this.mediaRecorder && this.mediaRecorder.state === 'recording') {
        this.mediaRecorder.stop();
      }
      if (this.mediaStream) {
        this.mediaStream.getTracks().forEach(track => track.stop());
        this.mediaStream = null;
      }
      this.cameraEnabled = false;
    },
    reportLearningProgress() {
      if (!this.username || !this.selectedCategory || !this.selectedItem) return;
      axios.post('/api/learning/progress', {
        username: this.username,
        chapter: this.selectedCategory,
        subchapter: this.selectedItem,
        learningDuration: Math.floor(this.learningDuration)
      }).catch(error => console.error('学习时长同步失败:', error));
